def factorial(n: int) -> int:
    """Factorial recursivo."""
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(10))  # 3628800

def permutar(elements: list) -> list[list]:
    """Genera todas las permutaciones de una lista."""
    if len(elements) <= 1:
        return [elements[:]]
    resultado = []
    for i, elem in enumerate(elements):
        resto = elements[:i] + elements[i+1:]
        for perm in permutar(resto):
            resultado.append([elem] + perm)
    return resultado

perms = permutar([1, 2, 3])
print(len(perms))  # 6

def potencia(base: float, exp: int) -> float:
    """Potencia recursiva eficiente (O(log n))."""
    if exp == 0:
        return 1
    if exp % 2 == 0:
        mitad = potencia(base, exp // 2)
        return mitad * mitad
    return base * potencia(base, exp - 1)

print(potencia(2, 10))  # 1024

def mcd(a: int, b: int) -> int:
    """Máximo común divisor por algoritmo de Euclides."""
    if b == 0:
        return a
    return mcd(b, a % b)

print(mcd(48, 18))  # 6

def fibonacci(n: int) -> int:
    """Fibonacci recursivo con memoización."""
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def _fib(k):
        if k < 2: return k
        return _fib(k-1) + _fib(k-2)
    return _fib(n)

print(fibonacci(30))  # 832040

